// HMAC-SHA256 — Nest stableStringify 와 동일 규칙. Webhook v2 는 body 를 item.body 에 둠.
function stableStringify(obj) {
  if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return '[' + obj.map(stableStringify).join(',') + ']';
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + stableStringify(obj[k])).join(',') + '}';
}

const crypto = require('crypto');
const secret = $env.ONQUEST_WEBHOOK_SECRET;
if (!secret) throw new Error('ONQUEST_WEBHOOK_SECRET is not configured');

const item = $input.first().json;
const headers = item.headers || {};
const signature = headers['x-onquest-signature'] || headers['X-OnQuest-Signature'];
const timestamp = headers['x-onquest-timestamp'] || headers['X-OnQuest-Timestamp'];
if (!signature || !timestamp) throw new Error('Missing signature headers');

const driftMs = Math.abs(Date.now() - new Date(timestamp).getTime());
if (driftMs > 5 * 60 * 1000) throw new Error('Timestamp out of window');

const payload =
  item.body !== undefined && item.body !== null && typeof item.body === 'object' && 'event' in item.body
    ? item.body
    : item;

const body = stableStringify(payload);
const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
if (signature !== expected) throw new Error('Invalid signature');

return [{ json: payload }];

